mapper.select:
select m.id, m.title, m.meeting_type, m.meeting_status, m.meeting_time, m.meeting_host, m.participation_info, m.file_info, m.attachment_info, m.ext_info, m.order_no, m.deleted, m.create_by, m.create_time, m.update_by, m.update_time, m.remark, COALESCE(t.topic_count, 0) as topic_count from bus_meeting_info m left join ( select meeting_id, count(*) as topic_count from bus_meeting_topic where deleted = 0 group by meeting_id ) t on m.id = t.meeting_id
m.deleted = 0 and m.title like concat('%', #{title}, '%') and m.meeting_status = #{meetingStatus} and m.meeting_time between #{params.beginMeetingTime} and #{params.endMeetingTime}
order by m.meeting_time
